insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000002281', 'linking', '/ˈlɪŋkɪŋ/', 'noun', 'ligação de sons', 'Linking connects the final consonant of one word to the vowel that begins the next, as in ''turn it off''.', 'A ligação conecta a consoante final de uma palavra à vogal que começa a próxima, como em ''turn it off''.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002282', 'elision', '/ɪˈlɪʒən/', 'noun', 'elisão', 'Elision happens when a sound disappears in fast speech, as in ''next day'' sounding like ''nex day''.', 'A elisão acontece quando um som desaparece na fala rápida, como em ''next day'' soando como ''nex day''.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002283', 'assimilation', '/əˌsɪmɪˈleɪʃən/', 'noun', 'assimilação', 'Assimilation occurs when one sound changes to become more like a neighboring sound, as in ''handbag'' sounding like ''hambag''.', 'A assimilação ocorre quando um som muda para ficar parecido com o som vizinho, como em ''handbag'' soando como ''hambag''.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002284', 'connected speech', '/kəˈnektɪd spiːtʃ/', 'noun', 'fala conectada', 'In connected speech, words blend together instead of being pronounced separately.', 'Na fala conectada, as palavras se misturam em vez de serem pronunciadas separadamente.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002285', 'intonation', '/ˌɪntəˈneɪʃən/', 'noun', 'entonação', 'Intonation is the rise and fall of the voice while speaking.', 'Entonação é a subida e descida da voz ao falar.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002286', 'stress', '/stres/', 'noun', 'acento tônico', 'Word stress can completely change the meaning of a sentence in English.', 'O acento tônico pode mudar completamente o sentido de uma frase em inglês.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002287', 'gonna', '/ˈɡɒnə/', 'phrase', 'forma reduzida de "going to"', 'I''m gonna call you later tonight.', 'Eu vou te ligar mais tarde hoje à noite.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002288', 'wanna', '/ˈwɒnə/', 'phrase', 'forma reduzida de "want to"', 'Do you wanna join us for dinner?', 'Você quer se juntar a nós pro jantar?', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002289', 'gotta', '/ˈɡɒtə/', 'phrase', 'forma reduzida de "got to"', 'I gotta finish this report before five.', 'Eu preciso terminar esse relatório antes das cinco.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002290', 'hafta', '/ˈhæftə/', 'phrase', 'forma reduzida de "have to"', 'We hafta leave early tomorrow morning.', 'A gente precisa sair cedo amanhã de manhã.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002291', 'oughta', '/ˈɔːtə/', 'phrase', 'forma reduzida de "ought to"', 'You oughta check that email before sending it.', 'Você deveria checar esse e-mail antes de enviar.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002292', 'usta', '/ˈjuːstə/', 'phrase', 'forma reduzida de "used to"', 'She usta work at that company years ago.', 'Ela costumava trabalhar naquela empresa anos atrás.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002293', 'didja', '/ˈdɪdʒə/', 'phrase', 'forma reduzida de "did you"', 'Didja finish the report yet?', 'Você já terminou o relatório?', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002294', 'doncha', '/ˈdoʊntʃə/', 'phrase', 'forma reduzida de "don''t you"', 'Doncha think we should call first?', 'Você não acha que a gente deveria ligar antes?', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002295', 'whatcha', '/ˈwɒtʃə/', 'phrase', 'forma reduzida de "what are you"', 'Whatcha doing this weekend?', 'O que você vai fazer neste fim de semana?', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002296', 'gimme', '/ˈɡɪmi/', 'phrase', 'forma reduzida de "give me"', 'Gimme a minute to check the file.', 'Me dá um minuto pra checar o arquivo.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002297', 'lemme', '/ˈlemi/', 'phrase', 'forma reduzida de "let me"', 'Lemme know if you need any help.', 'Me avisa se precisar de ajuda.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002298', 'coulda', '/ˈkʊdə/', 'phrase', 'forma reduzida de "could have"', 'We coulda finished earlier if we had started on time.', 'A gente poderia ter terminado mais cedo se tivesse começado na hora.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002299', 'schwa', '/ʃwɑː/', 'noun', 'schwa (som vocálico neutro)', 'The schwa is the most common vowel sound in English, heard in unstressed syllables.', 'O schwa é o som vocálico mais comum do inglês, ouvido em sílabas átonas.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002300', 'weak form', '/wiːk fɔːrm/', 'noun', 'forma fraca', 'Function words like ''and'' and ''to'' usually have a weak form in natural speech.', 'Palavras funcionais como ''and'' e ''to'' geralmente têm uma forma fraca na fala natural.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002301', 'strong form', '/strɔːŋ fɔːrm/', 'noun', 'forma forte', 'The strong form of a word is used for emphasis or when it stands alone.', 'A forma forte de uma palavra é usada para ênfase ou quando ela aparece sozinha.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002302', 'content word', '/ˈkɒntent wɜːrd/', 'noun', 'palavra de conteúdo', 'Content words like nouns and verbs usually carry the main stress in a sentence.', 'Palavras de conteúdo, como substantivos e verbos, geralmente carregam o acento principal na frase.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002303', 'function word', '/ˈfʌŋkʃən wɜːrd/', 'noun', 'palavra funcional', 'Function words like prepositions and articles are often unstressed.', 'Palavras funcionais, como preposições e artigos, costumam ser átonas.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002304', 'syllable', '/ˈsɪləbəl/', 'noun', 'sílaba', 'Every English word has at least one stressed syllable.', 'Toda palavra em inglês tem pelo menos uma sílaba tônica.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002305', 'rhythm', '/ˈrɪðəm/', 'noun', 'ritmo', 'English has a stress-timed rhythm, unlike the syllable-timed rhythm of Portuguese.', 'O inglês tem um ritmo baseado em acento, diferente do ritmo silábico do português.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002306', 'pitch', '/pɪtʃ/', 'noun', 'altura da voz', 'Pitch rises naturally at the end of a yes-no question.', 'A altura da voz sobe naturalmente no final de uma pergunta de sim ou não.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002307', 'fluency', '/ˈfluːənsi/', 'noun', 'fluência', 'Fluency depends more on rhythm and connected speech than on perfect grammar.', 'A fluência depende mais do ritmo e da fala conectada do que da gramática perfeita.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002308', 'rising intonation', '/ˈraɪzɪŋ ˌɪntəˈneɪʃən/', 'noun', 'entonação ascendente', 'Rising intonation is common in yes-no questions, like ''Are you coming?''', 'A entonação ascendente é comum em perguntas de sim ou não, como ''Are you coming?''', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002309', 'falling intonation', '/ˈfɔːlɪŋ ˌɪntəˈneɪʃən/', 'noun', 'entonação descendente', 'Falling intonation is typical at the end of statements and wh- questions.', 'A entonação descendente é típica no final de afirmações e perguntas com wh-.', 'C1', array['pronunciation']),
('30000000-0000-0000-0000-000000002310', 'sentence stress', '/ˈsentəns stres/', 'noun', 'acento de frase', 'Sentence stress highlights the most important words in a sentence.', 'O acento de frase destaca as palavras mais importantes de uma frase.', 'C1', array['pronunciation']);

