('20000000-0000-0000-0000-000000000381', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002283", "show_image": false}'),
('20000000-0000-0000-0000-000000000381', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002285", "show_image": false}'),
('20000000-0000-0000-0000-000000000381', 'multiple_choice', 4, '{"question": "___ connects the final consonant of one word to the vowel that begins the next.", "audio_text": null, "options": ["Linking", "Stress", "Fluency"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000381', 'multiple_choice', 5, '{"question": "___ occurs when one sound changes to become more like a neighboring sound.", "audio_text": null, "options": ["Assimilation", "Intonation", "Rhythm"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000381', 'matching', 6, '{"pairs": [{"left": "linking", "right": "ligação de sons"}, {"left": "elision", "right": "elisão"}, {"left": "assimilation", "right": "assimilação"}, {"left": "connected speech", "right": "fala conectada"}, {"left": "intonation", "right": "entonação"}, {"left": "stress", "right": "acento tônico"}]}'),
('20000000-0000-0000-0000-000000000381', 'fill_blank', 7, '{"sentence": "___ happens when a sound disappears in fast speech.", "options": ["Elision", "Linking", "Pitch"], "correct": "Elision", "translation": "A elisão acontece quando um som desaparece na fala rápida."}'),
('20000000-0000-0000-0000-000000000381', 'fill_blank', 8, '{"sentence": "Word ___ can completely change the meaning of a sentence in English.", "options": ["stress", "elision", "linking"], "correct": "stress", "translation": "O acento tônico pode mudar completamente o sentido de uma frase em inglês."}'),
('20000000-0000-0000-0000-000000000381', 'word_order', 9, '{"words": ["In", "connected", "speech", "words", "blend", "together", "instead", "of", "being", "pronounced", "separately"], "correct_sentence": "In connected speech words blend together instead of being pronounced separately", "translation": "Na fala conectada, as palavras se misturam em vez de serem pronunciadas separadamente"}'),
('20000000-0000-0000-0000-000000000381', 'word_order', 10, '{"words": ["Intonation", "is", "the", "rise", "and", "fall", "of", "the", "voice", "while", "speaking"], "correct_sentence": "Intonation is the rise and fall of the voice while speaking", "translation": "Entonação é a subida e descida da voz ao falar"}'),
('20000000-0000-0000-0000-000000000381', 'reading', 11, '{"passage": "Natural spoken English relies on connected speech. Linking joins the end of one word to the beginning of the next, as in ''turn it off''. Elision drops sounds in fast speech, and assimilation changes a sound to match its neighbor, as in ''handbag'' sounding like ''hambag''. On top of this, intonation and stress shape meaning and emotion.", "translation": "O inglês falado naturalmente depende da fala conectada. A ligação une o fim de uma palavra ao início da próxima, como em ''turn it off''. A elisão elimina sons na fala rápida, e a assimilação muda um som para combinar com o vizinho, como em ''handbag'' soando como ''hambag''. Além disso, entonação e acento moldam significado e emoção.", "question": "What does assimilation do, according to the text?", "options": ["Changes a sound to match its neighbor", "Adds an extra syllable", "Removes all stress"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000381', 'listening', 12, '{"audio_text": "Linking connects the final consonant of one word to the vowel that begins the next. Assimilation occurs when one sound changes to become more like a neighboring sound. Word stress can completely change the meaning of a sentence in English.", "question": "What can completely change the meaning of a sentence, according to the audio?", "options": ["Word stress", "Linking", "Assimilation"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000381', 'dictation', 13, '{"audio_text": "In connected speech, words blend together instead of being pronounced separately.", "expected": "In connected speech, words blend together instead of being pronounced separately."}'),
('20000000-0000-0000-0000-000000000381', 'typing', 14, '{"prompt_pt": "Traduza: ''A ligação e a assimilação fazem parte da fala conectada natural do inglês.''", "expected": "Linking and assimilation are part of natural connected speech in English.", "ai_review": true}'),

-- Lição 382: Formas reduzidas de verbos modais e semi-modais (gonna, wanna, gotta, hafta, oughta, usta)
('20000000-0000-0000-0000-000000000382', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002287", "show_image": false}'),
('20000000-0000-0000-0000-000000000382', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002289", "show_image": false}'),
('20000000-0000-0000-0000-000000000382', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002292", "show_image": false}'),
('20000000-0000-0000-0000-000000000382', 'multiple_choice', 4, '{"question": "I''m ___ call you later tonight.", "audio_text": null, "options": ["gonna", "coulda", "usta"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000382', 'multiple_choice', 5, '{"question": "We ___ leave early tomorrow morning.", "audio_text": null, "options": ["hafta", "oughta", "wanna"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000382', 'matching', 6, '{"pairs": [{"left": "gonna", "right": "forma reduzida de \"going to\""}, {"left": "wanna", "right": "forma reduzida de \"want to\""}, {"left": "gotta", "right": "forma reduzida de \"got to\""}, {"left": "hafta", "right": "forma reduzida de \"have to\""}, {"left": "oughta", "right": "forma reduzida de \"ought to\""}, {"left": "usta", "right": "forma reduzida de \"used to\""}]}'),
('20000000-0000-0000-0000-000000000382', 'fill_blank', 7, '{"sentence": "I ___ finish this report before five.", "options": ["gotta", "usta", "gonna"], "correct": "gotta", "translation": "Eu preciso terminar esse relatório antes das cinco."}'),
('20000000-0000-0000-0000-000000000382', 'fill_blank', 8, '{"sentence": "You ___ check that email before sending it.", "options": ["oughta", "hafta", "gotta"], "correct": "oughta", "translation": "Você deveria checar esse e-mail antes de enviar."}'),
('20000000-0000-0000-0000-000000000382', 'word_order', 9, '{"words": ["Do", "you", "wanna", "join", "us", "for", "dinner"], "correct_sentence": "Do you wanna join us for dinner", "translation": "Você quer se juntar a nós pro jantar?"}'),
('20000000-0000-0000-0000-000000000382', 'word_order', 10, '{"words": ["She", "usta", "work", "at", "that", "company", "years", "ago"], "correct_sentence": "She usta work at that company years ago", "translation": "Ela costumava trabalhar naquela empresa anos atrás"}'),
('20000000-0000-0000-0000-000000000382', 'reading', 11, '{"passage": "In casual native speech, ''going to'', ''want to'' and ''got to'' are often reduced to ''gonna'', ''wanna'' and ''gotta''. Similarly, ''have to'' becomes ''hafta'', ''ought to'' becomes ''oughta'', and ''used to'' becomes ''usta''. These reduced forms are extremely common in spoken English, though they are usually avoided in formal writing.", "translation": "Na fala nativa informal, ''going to'', ''want to'' e ''got to'' costumam ser reduzidos para ''gonna'', ''wanna'' e ''gotta''. Da mesma forma, ''have to'' vira ''hafta'', ''ought to'' vira ''oughta'', e ''used to'' vira ''usta''. Essas formas reduzidas são extremamente comuns no inglês falado, embora geralmente sejam evitadas na escrita formal.", "question": "Where are these reduced forms usually avoided, according to the text?", "options": ["In formal writing", "In casual conversation", "In song lyrics"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000382', 'listening', 12, '{"audio_text": "I''m gonna call you later tonight. We hafta leave early tomorrow morning. You oughta check that email before sending it.", "question": "When will they leave, according to the audio?", "options": ["Early tomorrow morning", "Later tonight", "Next week"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000382', 'dictation', 13, '{"audio_text": "I gotta finish this report before five.", "expected": "I gotta finish this report before five."}'),
('20000000-0000-0000-0000-000000000382', 'typing', 14, '{"prompt_pt": "Traduza usando linguagem falada informal: ''Eu vou ligar mais tarde; a gente precisa sair cedo amanhã.''", "expected": "I''m gonna call later; we hafta leave early tomorrow.", "ai_review": true}'),

-- Lição 383: Contrações informais na fala rápida (didja, doncha, whatcha, gimme, lemme, coulda)
