('20000000-0000-0000-0000-000000000384', 'fill_blank', 8, '{"sentence": "The ___ of a word is used for emphasis or when it stands alone.", "options": ["strong form", "weak form", "syllable"], "correct": "strong form", "translation": "A forma forte de uma palavra é usada para ênfase ou quando ela aparece sozinha."}'),
('20000000-0000-0000-0000-000000000384', 'word_order', 9, '{"words": ["Function", "words", "like", "and", "and", "to", "usually", "have", "a", "weak", "form", "in", "natural", "speech"], "correct_sentence": "Function words like and and to usually have a weak form in natural speech", "translation": "Palavras funcionais como and e to geralmente têm uma forma fraca na fala natural"}'),
('20000000-0000-0000-0000-000000000384', 'word_order', 10, '{"words": ["Every", "English", "word", "has", "at", "least", "one", "stressed", "syllable"], "correct_sentence": "Every English word has at least one stressed syllable", "translation": "Toda palavra em inglês tem pelo menos uma sílaba tônica"}'),
('20000000-0000-0000-0000-000000000384', 'reading', 11, '{"passage": "The schwa, a short, neutral vowel sound, appears in most unstressed syllables in English. Content words, like nouns, verbs and adjectives, usually carry the main stress and keep their strong form, while function words, like prepositions and articles, are often unstressed and reduced to a weak form using the schwa. Understanding syllables and stress patterns is key to sounding natural.", "translation": "O schwa, um som vocálico curto e neutro, aparece na maioria das sílabas átonas do inglês. Palavras de conteúdo, como substantivos, verbos e adjetivos, geralmente carregam o acento principal e mantêm sua forma forte, enquanto palavras funcionais, como preposições e artigos, costumam ser átonas e reduzidas a uma forma fraca usando o schwa. Entender sílabas e padrões de acento é essencial para soar natural.", "question": "What kind of words usually carry the main stress, according to the text?", "options": ["Content words", "Function words", "Weak forms"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000384', 'listening', 12, '{"audio_text": "The schwa is the most common vowel sound in English, heard in unstressed syllables. Content words like nouns and verbs usually carry the main stress in a sentence. Function words like prepositions and articles are often unstressed.", "question": "Where is the schwa heard, according to the audio?", "options": ["In unstressed syllables", "Only in content words", "Only at the end of sentences"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000384', 'dictation', 13, '{"audio_text": "Every English word has at least one stressed syllable.", "expected": "Every English word has at least one stressed syllable."}'),
('20000000-0000-0000-0000-000000000384', 'typing', 14, '{"prompt_pt": "Traduza: ''Palavras de conteúdo mantêm a forma forte, enquanto palavras funcionais costumam usar a forma fraca com o schwa.''", "expected": "Content words keep the strong form, while function words often use the weak form with the schwa.", "ai_review": true}'),

